'use strict';
const v272Init=Router.init.bind(Router);Router.init=async function(){const r=await v272Init();for(const e of document.querySelectorAll('.top-actions a[href="#field"],#business-menu,#audit-nav'))e.remove();const nav=document.querySelector('.sidebar nav'),report=nav.querySelector('[data-primary-route=reports]'),map=nav.querySelector('[data-primary-route="stock-map"]');if(report&&map)map.after(report);return r;};
const v272Select=StockMap.select.bind(StockMap);StockMap.select=async function(...args){await v272Select(...args);const detail=$('stock-map-detail');if(document.fullscreenElement===MapView.stage&&detail)MapView.stage.append(detail);};document.addEventListener('fullscreenchange',()=>{if(!document.fullscreenElement){const d=$('stock-map-detail');if(d&&d.parentElement===MapView.stage)document.querySelector('.stock-map-layout')?.append(d);}});
